/* dtg-pricing.css — extracted 2026-09-06 from 1 inline \3c style> block(s) in dtg-pricing.html (Rule 3). */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --dtg-pricing-gray: #666;
    --dtg-pricing-gray-dark: #333;
    --dtg-pricing-gray-2: #bdbdbd;
    --dtg-pricing-green-2: #5fd966;
    --dtg-pricing-green-3: #52c956;
    --dtg-pricing-red: #f87171;

    /* Phase 2d (2026-05-23): var() ref so PNW palette resolves via shell.css */
    --primary-color: var(--pnw-forest, var(--brand-500));
    --primary-dark: var(--pnw-forest-deep, var(--brand-600));
    --primary-light: var(--pnw-mist, var(--brand-100));
    --bg-color: var(--gray-50);
    --card-bg: var(--color-surface);
    --border-color: var(--gray-200);
    --text-primary: var(--dtg-pricing-gray-dark);
    --text-secondary: var(--dtg-pricing-gray);
    --warning-bg: var(--amber-100);
    --warning-border: var(--amber-400);
    --warning-text: var(--amber-800);
    --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 5%);
    --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 10%), 0 2px 4px -1px rgb(0 0 0 / 6%);
    --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 10%), 0 4px 6px -2px rgb(0 0 0 / 5%);
}
/* stylelint-enable color-no-hex */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-primary);
    line-height: 1.6;
}

/* Header */
.header {
    background: white;
    border-bottom: 1px solid var(--border-color);
    box-shadow: var(--shadow-sm);
    padding: 20px 0;
    margin-bottom: 40px;
}

.header-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.breadcrumb {
    color: var(--text-secondary);
    font-size: 14px;
    font-weight: 500;
}

.breadcrumb a {
    color: var(--primary-color);
    text-decoration: none;
    transition: color 0.3s ease;
}

.breadcrumb a:hover {
    color: var(--primary-dark);
    text-decoration: underline;
}

.search-wrapper {
    display: flex;
    align-items: center;
    gap: 15px;
    position: relative;
}

/* Search Results Dropdown */
.search-results {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: white;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    margin-top: 4px;
    max-height: 400px;
    overflow-y: auto;
    display: none;
    z-index: 1000;
    box-shadow: var(--shadow-md);
}

.search-results.active {
    display: block;
}

.search-loading {
    padding: 12px;
    text-align: center;
    color: var(--text-secondary);
}

.search-no-results {
    padding: 12px;
    text-align: center;
    color: var(--text-secondary);
}

.search-result-item {
    padding: 10px 12px;
    cursor: pointer;
    border-bottom: 1px solid var(--gray-100);
    transition: background-color 0.2s;
}

.search-result-item:hover {
    background-color: var(--gray-50);
}

.search-result-item:last-child {
    border-bottom: none;
}

.search-result-style {
    font-weight: 600;
    color: var(--text-primary);
}

.search-result-desc {
    color: var(--text-secondary);
    font-size: 0.875rem;
    margin-top: 2px;
}

.search-results-section {
    margin-bottom: 8px;
}

.search-results-title {
    padding: 8px 12px;
    background-color: var(--gray-100);
    font-weight: 600;
    font-size: 0.875rem;
    color: var(--gray-600);
}

.search-input {
    padding: 12px 16px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    font-size: 14px;
    font-weight: 500;
    width: 300px;
    transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

.search-input:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px rgb(76 179 84 / 10%);
}

.search-btn {
    background: var(--primary-color);
    color: white;
    border: none;
    padding: 12px 16px;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 600;
    transition: background-color 0.3s ease;
}

.search-btn:hover {
    background: var(--primary-dark);
}

/* Main Container */
.main-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

/* Loading State */
.loading {
    text-align: center;
    padding: 100px 20px;
    color: var(--text-secondary);
}

.loading i {
    font-size: 48px;
    margin-bottom: 20px;
    animation: spin 1s linear infinite;
}

@keyframes spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

/* Product Hero Section */
.product-hero {
    background: white;
    border-radius: 16px;
    box-shadow: var(--shadow-md);
    overflow: hidden;
    margin-bottom: 40px;
    transition: box-shadow 0.3s ease;
}

.product-hero:hover {
    box-shadow: var(--shadow-lg);
}

.product-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0;
    min-height: 500px;
}

/* Product Image Section */
.product-image-section {
    background: linear-gradient(135deg, var(--gray-50), var(--gray-200));
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 40px;
    position: relative;
}

.product-badge {
    position: absolute;
    top: 20px;
    left: 20px;
    background: var(--primary-color);
    color: white;
    padding: 8px 16px;
    border-radius: 20px;
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.image-gallery {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 20px;
    width: 100%;
    max-width: 450px;
}

.main-image-container {
    position: relative;
    width: 100%;
    height: 450px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: white;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 4px 6px rgb(0 0 0 / 10%);
}

.image-thumbnails {
    display: flex;
    gap: 8px;
    justify-content: center;
}

.image-thumbnail {
    width: 70px;
    height: 70px;
    border: 2px solid transparent;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: all 0.3s ease;
    background: white;
    box-shadow: 0 2px 4px rgb(0 0 0 / 10%);
}

.image-thumbnail:hover {
    border-color: var(--primary-color);
    transform: scale(1.05);
}

.image-thumbnail.active {
    border-color: var(--primary-color);
    box-shadow: 0 0 0 2px rgb(76 179 84 / 30%);
}

.image-thumbnail img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: contain;
    border-radius: 12px;
    transition: transform 0.3s ease;
    cursor: zoom-in;
}

.product-image:hover {
    transform: scale(1.2);
}

.image-placeholder {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--gray-200), var(--dtg-pricing-gray-2));
    border-radius: 12px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: var(--dtg-pricing-gray);
    font-size: 18px;
    font-weight: 600;
}

/* Product Info Section */
.product-info-section {
    padding: 40px;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.product-title {
    font-family: Poppins, sans-serif;
    font-size: 28px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 8px;
    line-height: 1.3;
}

.product-description {
    font-size: 16px;
    color: var(--text-secondary);
    margin-bottom: 24px;
    line-height: 1.6;
}

.product-details {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 32px;
}

.product-detail-item {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 14px;
    color: var(--text-secondary);
}

.product-detail-item i {
    color: var(--primary-color);
    width: 16px;
}

.product-detail-value {
    font-weight: 600;
    color: var(--text-primary);
}

/* Color Swatches */
.color-swatches-section {
    margin-bottom: 32px;
}

.color-swatches-title {
    font-size: 16px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 16px;
}

.color-swatches {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
}

.color-swatch {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: 2px solid var(--gray-200);
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
}

.color-swatch:hover {
    transform: scale(1.1);
    border-color: var(--primary-color);
}

.color-swatch.active {
    border-color: var(--primary-color);
    box-shadow: 0 0 0 2px rgb(76 179 84 / 30%);
}

/* Pricing Section */
.pricing-section {
    background: white;
    border-radius: 16px;
    box-shadow: var(--shadow-md);
    padding: 32px;
    margin-bottom: 40px;
}

.pricing-title {
    font-family: Poppins, sans-serif;
    font-size: 24px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 8px;
}

.pricing-subtitle {
    font-size: 14px;
    color: var(--text-secondary);
    margin-bottom: 32px;
}

/* Toggle Switch Pricing Interface */
.toggle-pricing-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
    margin-bottom: 32px;
}

.toggle-section {
    background: white;
    padding: 24px;
    border-radius: 12px;
    border: 2px solid var(--gray-200);
}

.toggle-section-title {
    font-size: 18px;
    font-weight: 700;
    color: var(--gray-800);
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 8px;
}

.toggle-section-title i {
    color: var(--brand-500);  /* Green icons to match DTF and Screen Print */
    font-size: 20px;
}

.toggle-section-subtitle {
    font-size: 14px;
    color: var(--gray-500);
    margin-top: -12px;
    margin-bottom: 20px;
}

/* 2x3 Grid for location cards */
.location-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px;
    background: var(--gray-50);
    border-radius: 8px;
    border: 2px solid var(--gray-200);
    transition: all 0.3s;
    cursor: pointer;  /* Make entire card clickable */
    user-select: none;  /* Prevent text selection on click */
}

.toggle-item:hover {
    border-color: var(--brand-500);
    transform: translateY(-2px);
    box-shadow: 0 4px 8px rgb(76 179 84 / 10%);
}

.toggle-item.active {
    background: var(--brand-100);
    border-color: var(--brand-500);
    border-width: 3px;
}

.toggle-item-label {
    font-size: 15px;
    font-weight: 600;
    color: var(--gray-800);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.toggle-item-size {
    font-size: 12px;
    font-weight: 400;
    color: var(--gray-500);
}

/* iOS-style toggle switch */
.toggle-switch {
    position: relative;
    width: 56px;
    height: 32px;
    background: var(--gray-300);
    border-radius: 16px;
    cursor: pointer;
    transition: background 0.3s;
}

.toggle-switch.on {
    background: var(--brand-500);
}

.toggle-switch-slider {
    position: absolute;
    top: 4px;
    left: 4px;
    width: 24px;
    height: 24px;
    background: white;
    border-radius: 50%;
    transition: transform 0.3s;
    box-shadow: 0 2px 4px rgb(0 0 0 / 20%);
}

.toggle-switch.on .toggle-switch-slider {
    transform: translateX(24px);
}

/* Quantity Tiers */
.tier-button {
    width: 100%;
    padding: 20px;
    margin-bottom: 12px;
    background: white;
    border: 2px solid var(--gray-200);
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    color: var(--gray-600);
    cursor: pointer;
    transition: all 0.3s;
    text-align: center;
}

.tier-button:hover {
    border-color: var(--brand-500);
    background: var(--color-floor-tint);
}

.tier-button.selected {
    background: white;
    border-color: var(--brand-500);
    border-width: 3px;
    color: var(--brand-500);
    box-shadow: 0 0 0 2px rgb(76 179 84 / 20%);
}

/* Live Price Display */
.live-price-display {
    position: relative;  /* Required for absolute-positioned tooltip */
    background: linear-gradient(135deg, var(--brand-500), var(--print-green));
    color: white;
    padding: 32px;
    border-radius: 12px;
    text-align: center;
    margin-top: 32px;
    box-shadow: 0 4px 12px rgb(76 179 84 / 30%);
}

.live-price-label {
    font-size: 16px;
    font-weight: 500;
    opacity: 0.9;
    margin-bottom: 8px;
}

.live-price-amount-wrapper {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
}

.live-price-amount {
    font-size: 48px;
    font-weight: 700;
    letter-spacing: -1px;
}

.upcharge-info-icon {
    font-size: 28px;
    color: white;
    opacity: 0.7;
    cursor: pointer;
    transition: all 0.3s ease;
    flex-shrink: 0;
}

.upcharge-info-icon:hover {
    opacity: 1;
    transform: scale(1.15);
}

.live-price-detail {
    font-size: 14px;
    opacity: 0.8;
    margin-top: 8px;
}

.live-price-fee {
    display: none;  /* Hidden by default */
    font-size: 18px;
    font-weight: 600;
    color: var(--bs-warning-ink);  /* Muted brown for subtle warning */
    margin-top: 16px;
    padding: 8px 16px;
    background: var(--amber-100);  /* Warning background */
    border-left: 2px solid var(--bs-warning);  /* Thinner yellow accent */
    border-radius: 4px;
}

.live-price-fee:not(:empty) {
    display: block;  /* Only show when has content */
}

/* Upcharge Tooltip Styles */
.upcharge-tooltip {
    position: absolute;
    bottom: calc(100% + 15px);  /* Position above the price display */
    left: 50%;
    transform: translateX(-50%);
    background: white;
    border: 2px solid var(--brand-500);
    border-radius: 12px;
    box-shadow: 0 8px 24px rgb(76 179 84 / 25%);
    padding: 20px;
    min-width: 280px;
    z-index: 1000;
    animation: tooltipFadeIn 0.3s ease;
}

@keyframes tooltipFadeIn {
    from {
        opacity: 0;
        transform: translateX(-50%) translateY(10px);
    }

    to {
        opacity: 1;
        transform: translateX(-50%) translateY(0);
    }
}

.upcharge-tooltip::after {
    content: '';
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    border: 10px solid transparent;
    border-top-color: var(--brand-500);
}

.upcharge-tooltip-header {
    font-size: 16px;
    font-weight: 700;
    color: var(--gray-800);
    margin-bottom: 12px;
    padding-bottom: 10px;
    border-bottom: 2px solid var(--gray-200);
}

.upcharge-tooltip-body {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.upcharge-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 0;
    font-size: 14px;
}

.upcharge-item-size {
    font-weight: 600;
    color: var(--gray-600);
}

.upcharge-item-price {
    font-weight: 700;
    color: var(--brand-500);
}

/* Setup Fee Badge Styles */
.setup-fee-badge {
    font-size: 24px;
    color: var(--amber-500);  /* Amber color */
    opacity: 0.85;
    cursor: pointer;
    transition: all 0.3s ease;
    flex-shrink: 0;
    margin-left: 12px;
}

.setup-fee-badge:hover {
    opacity: 1;
    transform: scale(1.15);
}

/* Setup Fee Tooltip Styles */
.setup-fee-tooltip {
    position: absolute;
    bottom: calc(100% + 15px);
    left: 50%;
    transform: translateX(-50%);
    background: white;
    border: 2px solid var(--amber-500);
    border-radius: 12px;
    box-shadow: 0 8px 24px rgb(245 158 11 / 25%);
    padding: 20px;
    min-width: 300px;
    z-index: 1000;
    animation: tooltipFadeIn 0.3s ease;
}

.setup-fee-tooltip::after {
    content: '';
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    border: 10px solid transparent;
    border-top-color: var(--amber-500);
}

.setup-fee-tooltip-header {
    font-size: 16px;
    font-weight: 700;
    color: var(--amber-800);
    margin-bottom: 12px;
    padding-bottom: 10px;
    border-bottom: 2px solid var(--amber-100);
    display: flex;
    align-items: center;
    gap: 8px;
}

.setup-fee-tooltip-body {
    font-size: 14px;
    color: var(--amber-900);
    line-height: 1.6;
}

.setup-fee-amount {
    font-size: 18px;
    font-weight: 700;
    color: var(--amber-500);
    margin: 8px 0;
}

.setup-fee-details {
    font-size: 13px;
    color: var(--amber-800);
    margin-top: 8px;
    padding-top: 8px;
    border-top: 1px solid var(--amber-100);
}

.upcharge-base {
    background: var(--gray-100);
    padding: 8px 12px;
    border-radius: 6px;
    margin-bottom: 8px;
}

#upcharge-info-icon {
    transition: all 0.3s ease;
}

#upcharge-info-icon:hover {
    opacity: 1;
    transform: scale(1.1);
}

/* Mobile responsive */
@media (width <= 768px) {
    .toggle-pricing-container {
        grid-template-columns: 1fr;
        gap: 20px;
    }

    .live-price-amount {
        font-size: 36px;
    }

    .upcharge-tooltip {
        position: fixed;
        bottom: auto;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        max-width: 90%;
        animation: tooltipFadeIn 0.3s ease;
    }

    .upcharge-tooltip::after {
        display: none;  /* Hide arrow on mobile */
    }

    #upcharge-info-icon {
        font-size: 18px;
    }
}

/* Mobile Responsiveness for Print Size Legend */
@media (width <= 768px) {
    .print-size-legend {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        flex-direction: column !important;
        text-align: center;
    }

    .legend-content {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        flex-direction: column !important;
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        gap: 4px !important;
    }

    .legend-content .size-item {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        border-right: none !important;
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        padding: 4px 0 !important;
    }
}

/* DTG Recommendations Section */
.dtg-recommendations-section {
    background: white;
    border-radius: 16px;
    box-shadow: var(--shadow-md);
    padding: 32px;
    margin: 40px 0;
}

.dtg-rec-title {
    font-family: Poppins, sans-serif;
    font-size: 24px;
    font-weight: 600;
    color: var(--gray-800);
    text-align: center;
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
}

.dtg-rec-subtitle {
    text-align: center;
    color: var(--gray-500);
    font-size: 16px;
    margin-bottom: 32px;
}

/* DTG Disclaimer Styles */
.dtg-disclaimer {
    display: flex;
    gap: 20px;
    background: linear-gradient(135deg, var(--amber-100), var(--orange-200));
    border: 2px solid var(--amber-500);
    border-radius: 12px;
    padding: 20px;
    margin: 25px 0 35px;
    box-shadow: 0 4px 6px rgb(245 158 11 / 10%);
}

.dtg-disclaimer-icon {
    flex-shrink: 0;
    font-size: 32px;
    color: var(--amber-600);
}

.dtg-disclaimer-content h4 {
    margin: 0 0 12px;
    color: var(--amber-800);
    font-size: 18px;
    font-weight: 600;
}

.dtg-disclaimer-content ul {
    margin: 0;
    padding-left: 0;
    list-style: none;
}

.dtg-disclaimer-content li {
    margin-bottom: 8px;
    color: var(--amber-900);
    line-height: 1.5;
}

.dtg-disclaimer-content li:last-child {
    margin-bottom: 0;
}

.dtg-recommendations-grid {
    display: flex;
    overflow: auto hidden;
    gap: 20px;
    margin-top: 24px;
    padding: 10px 0 20px;
    scroll-behavior: smooth;
    -webkit-overflow-scrolling: touch; /* iOS smooth scrolling */
}

.dtg-recommendations-grid::-webkit-scrollbar {
    height: 8px;
}

.dtg-recommendations-grid::-webkit-scrollbar-track {
    background: var(--slate-100);
    border-radius: 4px;
}

.dtg-recommendations-grid::-webkit-scrollbar-thumb {
    background: var(--gray-300);
    border-radius: 4px;
}

.dtg-recommendations-grid::-webkit-scrollbar-thumb:hover {
    background: var(--gray-400);
}

.dtg-product-card {
    background: white;
    border: 1px solid var(--gray-200);
    border-radius: 12px;
    overflow: hidden;
    transition: all 0.3s ease;
    position: relative;
    flex: 0 0 280px; /* Fixed width for horizontal scroll */
    min-height: 420px; /* Consistent height */
    display: flex;
    flex-direction: column;
}

.dtg-product-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 24px rgb(0 0 0 / 10%);
    border-color: var(--brand-500);
}

.dtg-card-badge {
    position: absolute;
    top: 12px;
    right: 12px;
    background: var(--brand-500);
    color: white;
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 12px;
    font-weight: 600;
    z-index: 1;
}

.dtg-card-image {
    width: 100%;
    height: 200px;
    background: var(--gray-50);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.dtg-card-image img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    transition: transform 0.3s ease;
}

.dtg-product-card:hover .dtg-card-image img {
    transform: scale(1.05);
}

/* Mobile responsiveness for DTG recommendations */
@media (width <= 768px) {
    .dtg-recommendations-section {
        padding: 20px 15px;
        margin: 20px 0;
    }

    .dtg-rec-title {
        font-size: 20px;
    }

    .dtg-recommendations-grid {
        gap: 16px;
        padding: 10px 0 16px;
    }

    .dtg-product-card {
        flex: 0 0 260px; /* Slightly smaller on tablets */
        min-height: 400px;
    }
}

@media (width <= 480px) {
    .dtg-recommendations-grid {
        gap: 12px;
        padding: 8px 0 12px;
    }

    .dtg-product-card {
        flex: 0 0 240px; /* Smaller on phones */
        min-height: 380px;
    }

    .dtg-product-badge {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        font-size: 10px !important;
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        padding: 3px 6px !important;
    }

    .dtg-card-title {
        font-size: 16px;
    }

    .dtg-card-rating {
        font-size: 12px;
    }
}

.dtg-card-content {
    padding: 16px;
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.dtg-card-title {
    font-size: 18px;
    font-weight: 600;
    color: var(--gray-800);
    margin: 0 0 4px;
}

.dtg-card-subtitle {
    font-size: 14px;
    color: var(--gray-600);
    margin: 0 0 4px;
}

.dtg-card-brand {
    font-size: 12px;
    color: var(--gray-400);
    margin: 0 0 12px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.dtg-card-rating {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
    font-size: 14px;
}

.dtg-card-rating .stars {
    color: var(--amber-400);
    letter-spacing: 2px;
}

.dtg-card-rating .sales {
    color: var(--gray-500);
    font-size: 12px;
}

.dtg-card-colors {
    background: var(--gray-50);
    border-radius: 8px;
    padding: 8px 12px;
    margin-bottom: 12px;
    font-size: 13px;
    line-height: 1.4;
}

.dtg-card-colors strong {
    color: var(--gray-600);
    display: block;
    margin-bottom: 4px;
}

.dtg-card-warning {
    background: var(--red-50);
    color: var(--red-600);
    border-radius: 8px;
    padding: 8px 12px;
    margin-bottom: 12px;
    font-size: 12px;
    line-height: 1.4;
}

.dtg-card-button {
    width: 100%;
    background: linear-gradient(135deg, var(--brand-500) 0%, var(--dtg-pricing-green-2) 100%);
    color: white;
    border: none;
    border-radius: 8px;
    padding: 10px 16px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 12px;
}

.dtg-card-button:hover {
    background: linear-gradient(135deg, var(--brand-600) 0%, var(--dtg-pricing-green-3) 100%);
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgb(76 179 84 / 30%);
}

/* Mobile Responsiveness */
@media (width <= 768px) {
    .product-content {
        grid-template-columns: 1fr;
    }

    .main-container {
        padding: 0 15px;
    }

    .product-image-section,
    .product-info-section {
        padding: 24px;
    }

    .pricing-section,
    .order-info-section {
        padding: 24px;
    }
}

/* Product Grouping Styles */
.dtg-product-section {
    margin-bottom: 32px;
}

.dtg-section-title {
    font-size: 22px;
    font-weight: 700;
    color: var(--gray-800);
    margin: 0 0 16px;
    padding: 12px 16px;
    background: linear-gradient(135deg, var(--slate-50) 0%, var(--slate-200) 100%);
    border-left: 4px solid var(--green-600);
    border-radius: 8px;
    display: flex;
    align-items: center;
    gap: 10px;
}

.dtg-section-title i {
    color: var(--green-600);
    font-size: 20px;
}

.dtg-section-grid {
    display: flex;
    overflow: auto hidden;
    gap: 16px;
    margin-top: 16px;
    padding: 8px 0 16px;
    scroll-behavior: smooth;
    -webkit-overflow-scrolling: touch;
}

.dtg-section-grid::-webkit-scrollbar {
    height: 6px;
}

.dtg-section-grid::-webkit-scrollbar-track {
    background: var(--slate-50);
    border-radius: 3px;
}

.dtg-section-grid::-webkit-scrollbar-thumb {
    background: var(--gray-300);
    border-radius: 3px;
}

@media (width <= 768px) {
    .dtg-section-grid {
        gap: 14px;
        padding: 6px 0 12px;
    }

    .dtg-section-title {
        font-size: 20px;
        padding: 10px 14px;
    }

    .dtg-product-section {
        margin-bottom: 24px;
    }
}

@media (width <= 480px) {
    .dtg-section-title {
        font-size: 18px;
        padding: 8px 12px;
    }

    .dtg-section-title i {
        font-size: 18px;
    }
}

/* 2026-09-06 review: the hidden attribute must beat any display rule */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }
.calc-inline-alert { margin: 12px auto; max-width: 960px; padding: 12px 16px; border-radius: 8px; background: var(--red-100); color: var(--red-800); border: 1px solid var(--dtg-pricing-red); font-weight: 600; }

