/* stylelint-disable declaration-no-important -- override stack: this calculator page layers fix/override sheets and JS-injected styles; the flags come out together when the page is untangled (2026-09-07) */

/* dtf-pricing.css — extracted 2026-09-06 from 2 inline \3c style> block(s) in dtf-pricing.html (Rule 3). */

/* CRITICAL: Override blue theme with green - MUST be inline to override JS */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --dtf-pricing-gray: #666;
    --dtf-pricing-gray-dark: #333;
    --dtf-pricing-teal: #add;
    --dtf-pricing-cyan: #007bff;
    --dtf-pricing-cyan-2: #0056b3;
    --dtf-pricing-gray-2: #bdbdbd;
    --dtf-pricing-red: #f87171;

    /* Phase 2d (2026-05-23): var() ref so PNW palette resolves via shell.css */
    --primary-color: var(--pnw-forest, var(--brand-500)) !important;  /* PNW forest */
    --primary: var(--pnw-forest, var(--brand-500)) !important;
    --primary-dark: var(--pnw-forest-deep, var(--brand-600)) !important;
    --primary-light: var(--pnw-mist, var(--brand-100)) !important;
    --nwca-primary: var(--pnw-forest, var(--brand-500)) !important;
}
/* stylelint-enable color-no-hex */

/* Enhanced Header Styles for DTF */
body.dtf-pricing-page {
    padding-top: 180px; /* Space for fixed header */
}

.enhanced-pricing-header {
    background: white;
    box-shadow: 0 2px 8px rgb(0 0 0 / 10%);
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 1000;
}

/* Top contact bar */
.header-contact-bar {
    background: var(--brand-600);  /* Updated to match DTG dark green */
    color: white;
    padding: 10px 0;
    font-size: 14px;
}

.contact-bar-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.contact-info {
    display: flex;
    gap: 25px;
    align-items: center;
}

.contact-item {
    display: flex;
    align-items: center;
    gap: 8px;
}

.contact-item i {
    font-size: 13px;
    opacity: 0.9;
}

.business-hours {
    font-size: 13px;
    opacity: 0.9;
}

/* Main navigation header */
.header-nav {
    padding: 15px 0;
    background: white;
    border-bottom: 1px solid var(--gray-200);
}

.nav-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo-section {
    display: flex;
    align-items: center;
}

.logo-link {
    display: inline-block;
}

.logo-image {
    height: 40px;
    width: auto;
}

/* Pricing Context Bar */
.pricing-context-bar {
    background: var(--gray-50);
    border-bottom: 2px solid var(--brand-500);  /* Updated to match DTG green */
    padding: 15px 0;
}

.context-bar-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.breadcrumb {
    font-size: 18px;
    font-weight: 600;
    color: var(--brand-500);  /* Updated to match DTG green */
}

/* Live Pricing Display */
.header-live-pricing {
    display: flex;
    gap: 30px;
    align-items: center;
}

.header-price-item {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.header-price-label {
    font-size: 14px;
    color: var(--dtf-pricing-gray);
    font-weight: 500;
}

.header-price-value {
    font-size: 20px;
    font-weight: 700;
    color: var(--dtf-pricing-gray-dark);
}

.header-price-value.highlight {
    color: var(--brand-500);  /* Updated to match DTG green */
    font-size: 24px;
}

/* Responsive adjustments */
@media (width <= 768px) {
    body.dtf-pricing-page {
        padding-top: 220px;
    }

    .contact-bar-content {
        flex-direction: column;
        gap: 10px;
        text-align: center;
    }

    .contact-info {
        flex-direction: column;
        gap: 8px;
    }

    .context-bar-content {
        flex-direction: column;
        gap: 15px;
        text-align: center;
    }

    .header-live-pricing {
        flex-direction: column;
        gap: 10px;
    }
}

/* Hide universal header since we're using enhanced header */
#universal-header-container {
    display: none !important;
}

/* Force green header styling */
#universal-header-container .header-main,
.universal-header,
.pricing-header,
.header-container {
    background: linear-gradient(135deg, var(--brand-500) 0%, var(--brand-600) 100%) !important;  /* Updated to match DTG gradient */
}

/* Override any blue colors in buttons and links */
.btn-primary,
.action-btn,
.dtf-btn,
button[type="submit"] {
    background-color: var(--brand-500) !important;  /* Updated to match DTG green */
    border-color: var(--brand-500) !important;
}

.btn-primary:hover,
.action-btn:hover,
.dtf-btn:hover,
button[type="submit"]:hover {
    background-color: var(--brand-600) !important;  /* Updated to match DTG dark green */
    border-color: var(--brand-600) !important;
}

a {
    color: var(--brand-500) !important;  /* Updated to match DTG green */
}

/* DTF Calculator specific overrides */
.dtf-calculator-header {
    background: var(--brand-500) !important;  /* Updated to match DTG green */
}

.dtf-price-display {
    color: var(--brand-500) !important;  /* Updated to match DTG green */
    border-color: var(--brand-500) !important;
}

/* Critical internal-only hiding styles - must be inline for immediate effect */
.internal-only {
    display: none !important;
}

.accordion-item.internal-only {
    display: none !important;
}

body.show-internal .internal-only,
body.show-internal .accordion-item.internal-only {
    display: block !important;
}

/* Page layout styles */
.product-page-columns-container {
    display: flex;
    flex-direction: row;
    gap: 20px;
    margin-top: 20px;
}

.product-context-column {
    flex: 0 0 350px;
    min-width: 0;
}

.product-interactive-column {
    flex: 1;
    min-width: 0;
}

/* Hide old calculator sections */
#add-to-cart-section {
    display: none;
}

/* Page header styles */
.page-header {
    background: linear-gradient(135deg, var(--dtf-pricing-cyan), var(--dtf-pricing-cyan-2));
    color: white;
    padding: 30px 0;
    margin-bottom: 30px;
    box-shadow: 0 4px 15px rgb(0 0 0 / 10%);
}

.page-header h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 10px;
}

.page-header p {
    font-size: 1.1rem;
    opacity: 0.9;
}

@media (width <= 992px) {
    .product-page-columns-container {
        flex-direction: column;
    }

    .product-context-column {
        flex: 1;
        max-width: 100%;
    }

    .page-header h1 {
        font-size: 2rem;
    }
}

/* Breadcrumb Links */
.breadcrumb a {
    color: var(--primary-color);
    text-decoration: none;
    transition: color 0.3s ease;
}

.breadcrumb a:hover {
    color: var(--primary-dark);
    text-decoration: underline;
}

/* Search Wrapper */
.search-wrapper {
    display: flex;
    align-items: center;
    gap: 15px;
    position: relative;
}

.search-input {
    padding: 12px 16px;
    border: 1px solid var(--gray-200);
    border-radius: 8px;
    font-size: 14px;
    font-weight: 500;
    width: 300px;
    transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

.search-input:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px rgb(58 124 82 / 10%);
}

.search-btn {
    background: var(--primary-color);
    color: white;
    border: none;
    padding: 12px 16px;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 600;
    transition: background-color 0.3s ease;
}

.search-btn:hover {
    background: var(--primary-dark);
}

/* Search Results Dropdown */
.search-results {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: white;
    border: 1px solid var(--gray-200);
    border-radius: 8px;
    margin-top: 4px;
    max-height: 400px;
    overflow-y: auto;
    display: none;
    z-index: 1000;
    box-shadow: 0 4px 6px rgb(0 0 0 / 10%);
}

.search-results.active {
    display: block;
}

.search-loading {
    padding: 12px;
    text-align: center;
    color: var(--dtf-pricing-gray);
}

.search-no-results {
    padding: 12px;
    text-align: center;
    color: var(--dtf-pricing-gray);
}

.search-result-item {
    padding: 10px 12px;
    cursor: pointer;
    border-bottom: 1px solid var(--gray-100);
    transition: background-color 0.2s;
}

.search-result-item:hover {
    background-color: var(--gray-50);
}

.search-result-item:last-child {
    border-bottom: none;
}

.search-result-style {
    font-weight: 600;
    color: var(--dtf-pricing-gray-dark);
}

.search-result-desc {
    color: var(--dtf-pricing-gray);
    font-size: 0.875rem;
    margin-top: 2px;
}

/* Loading State */
.loading {
    text-align: center;
    padding: 100px 20px;
    color: var(--dtf-pricing-gray);
}

.loading i {
    font-size: 48px;
    margin-bottom: 20px;
    animation: spin 1s linear infinite;
}

@keyframes spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

/* Product Hero Section */
.product-hero {
    background: white;
    border-radius: 16px;
    box-shadow: 0 4px 6px rgb(0 0 0 / 10%);
    overflow: hidden;
    margin-bottom: 40px;
    transition: box-shadow 0.3s ease;
}

.product-hero:hover {
    box-shadow: 0 10px 15px rgb(0 0 0 / 10%);
}

.product-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0;
    min-height: 500px;
}

/* Product Image Section */
.product-image-section {
    background: linear-gradient(135deg, var(--gray-50), var(--gray-200));
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 40px;
    position: relative;
}

.product-badge {
    position: absolute;
    top: 20px;
    left: 20px;
    background: var(--primary-color);
    color: white;
    padding: 8px 16px;
    border-radius: 20px;
