/* Screen reader only utility class for accessibility */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Enhanced Header Styles for Screen Print */

/* DTG-Style Header */
.header {
    background: white;
    border-bottom: 1px solid var(--gray-200);
    box-shadow: 0 1px 2px 0 rgb(0 0 0 / 5%);
    padding: 20px 0;
    margin-bottom: 40px;
}

.header-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.breadcrumb {
    color: var(--screen-print-pricing-gray);
    font-size: 14px;
    font-weight: 500;
}

.breadcrumb a {
    color: var(--brand-500);  /* Updated to match DTG/DTF green */
    text-decoration: none;
    transition: color 0.3s ease;
}

.breadcrumb a:hover {
    color: var(--brand-600);
    text-decoration: underline;
}

.search-wrapper {
    display: flex;
    align-items: center;
    gap: 15px;
    position: relative;
}

/* Search Results Dropdown */
.search-results {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: white;
    border: 1px solid var(--gray-200);
    border-radius: 8px;
    margin-top: 4px;
    max-height: 400px;
    overflow-y: auto;
    display: none;
    z-index: 1000;
    box-shadow: 0 4px 6px -1px rgb(0 0 0 / 10%), 0 2px 4px -1px rgb(0 0 0 / 6%);
}

.search-results.active {
    display: block;
}

.search-loading {
    padding: 12px;
    text-align: center;
    color: var(--screen-print-pricing-gray);
}

.search-no-results {
    padding: 12px;
    text-align: center;
    color: var(--screen-print-pricing-gray);
}

.search-result-item {
    padding: 10px 12px;
    cursor: pointer;
    border-bottom: 1px solid var(--gray-100);
    transition: background-color 0.2s;
}

.search-result-item:hover {
    background-color: var(--gray-50);
}

.search-result-item:last-child {
    border-bottom: none;
}

.search-result-style {
    font-weight: 600;
    color: var(--screen-print-pricing-gray-dark);
}

.search-result-desc {
    color: var(--screen-print-pricing-gray);
    font-size: 0.875rem;
    margin-top: 2px;
}

.search-input {
    padding: 12px 16px;
    border: 1px solid var(--gray-200);
    border-radius: 8px;
    font-size: 14px;
    font-weight: 500;
    width: 300px;
    transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

.search-input:focus {
    outline: none;
    border-color: var(--brand-500);  /* Updated to match DTG/DTF green */
    box-shadow: 0 0 0 3px rgb(76 179 84 / 10%);  /* Updated shadow color */
}

.search-btn {
    background: var(--brand-500);  /* Updated to match DTG/DTF green */
    color: white;
    border: none;
    padding: 12px 16px;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 600;
    transition: background-color 0.3s ease;
}

.search-btn:hover {
    background: var(--brand-600);
}

/* Hide universal header */
#universal-header-container {
    display: none !important;
}

/* ========================================
   DTG-STYLE LAYOUT: HERO SECTION AT TOP
   ======================================== */

/* Container */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

/* Product Hero Section - Full Width at Top */
.product-hero-section {
    background: white;
    border-radius: 16px;
    box-shadow: 0 4px 6px -1px rgb(0 0 0 / 10%), 0 2px 4px -1px rgb(0 0 0 / 6%);
    overflow: hidden;
    margin-bottom: 40px;
    transition: box-shadow 0.3s ease;
}

.product-hero-section:hover {
    box-shadow: 0 10px 15px -3px rgb(0 0 0 / 10%), 0 4px 6px -2px rgb(0 0 0 / 5%);
}

/* DTG-Style Two-Column Grid */
.product-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0;
    min-height: 500px;
}

/* Product Image Section (Left Column) */
.product-image-section {
    background: linear-gradient(135deg, var(--gray-50), var(--gray-200));
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 40px;
    position: relative;
}

.product-badge {
    position: absolute;
    top: 20px;
    left: 20px;
    background: var(--brand-600);
    color: white;
    padding: 8px 16px;
    border-radius: 20px;
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.image-gallery {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 20px;
    width: 100%;
    max-width: 450px;
}

.main-image-container {
    position: relative;
    width: 100%;
    height: 450px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: white;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 4px 6px rgb(0 0 0 / 10%);
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: contain;
    border-radius: 12px;
    transition: transform 0.3s ease;
    cursor: zoom-in;
}

.product-image:hover {
    transform: scale(1.2);
}

.image-placeholder {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--gray-200), var(--screen-print-pricing-gray-2));
    border-radius: 12px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: var(--screen-print-pricing-gray);
    font-size: 18px;
    font-weight: 600;
}

.image-thumbnails {
    display: flex;
    gap: 8px;
    justify-content: center;
}

.image-thumbnail {
    width: 70px;
    height: 70px;
    border: 2px solid transparent;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: all 0.3s ease;
    background: white;
    box-shadow: 0 2px 4px rgb(0 0 0 / 10%);
}

.image-thumbnail:hover {
    border-color: var(--brand-600);
    transform: scale(1.05);
}

.image-thumbnail.active {
    border-color: var(--brand-600);
    box-shadow: 0 0 0 2px rgb(45 95 63 / 30%);
}

.image-thumbnail img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Product Info Section (Right Column) */
.product-info-section {
    padding: 40px;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.product-title {
    font-family: Poppins, sans-serif;
    font-size: 28px;
    font-weight: 700;
    color: var(--gray-800);
    margin-bottom: 8px;
    line-height: 1.3;
}

.product-description {
    font-size: 16px;
    color: var(--gray-500);
    margin-bottom: 24px;
    line-height: 1.6;
}

.product-details {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 32px;
}

.product-detail-item {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 14px;
    color: var(--gray-500);
}

.product-detail-item i {
    color: var(--brand-600);
    font-size: 16px;
}

.product-detail-value {
    font-weight: 600;
    color: var(--gray-800);
}

/* Color Swatches Section */
.color-swatches-section {
    margin-top: 24px;
}

.color-swatches-title {
    font-size: 16px;
    font-weight: 600;
    color: var(--gray-800);
    margin-bottom: 16px;
}

.color-swatches {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
}

.color-swatch {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: 2px solid var(--gray-200);
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
}

.color-swatch:hover {
    transform: scale(1.1);
    border-color: var(--brand-600);
}

.color-swatch.active {
    border-color: var(--brand-600);
    box-shadow: 0 0 0 2px rgb(45 95 63 / 30%);
}

/* Pricing Calculator Section - Full Width Below Product */
.pricing-calculator-section {
    max-width: 1200px;
    margin: 0 auto 40px;
    background: white;
    border-radius: 16px;
    box-shadow: 0 4px 6px -1px rgb(0 0 0 / 10%), 0 2px 4px -1px rgb(0 0 0 / 6%);
    padding: 30px;
}

/* Remove old two-column layout */
.product-page-columns-container {
    display: none;
}

.product-context-column,
.product-interactive-column {
    display: none;
}

/* Screen Print Calculator V2 Styles */
.sp-calculator {
    background: var(--gray-50);
    border-radius: 8px;
    padding: 25px;
    margin: 20px 0;
    box-shadow: 0 2px 8px rgb(0 0 0 / 10%);
}

.sp-title {
    color: var(--brand-500) !important;
    font-size: 1.5em;
    margin: 0 0 20px;
    font-weight: 600;
}

.sp-layout {
    display: grid;
    grid-template-columns: 1.5fr 1fr;
    gap: 30px;
    align-items: start;
}

/* Controls */
.sp-controls {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.sp-control-group {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.sp-control-group label {
    font-weight: 600;
    color: var(--screen-print-pricing-gray-dark);
}

.sp-input, .sp-select {
    padding: 10px;
    border: 2px solid var(--store-line);
    border-radius: 4px;
    font-size: 1em;
    transition: border-color 0.3s;
}

.sp-input:focus, .sp-select:focus {
    outline: none;
    border-color: var(--brand-500) !important;
}

.sp-help-text {
    font-size: 0.85em;
    color: var(--screen-print-pricing-gray);
    font-style: italic;
}

.sp-checkbox-label {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    font-weight: 600;
}

.sp-checkbox-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    cursor: pointer;
}

/* Buttons */
.sp-btn {
    padding: 10px 16px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.95em;
    font-weight: 600;
    transition: all 0.3s;
}

.sp-btn-add {
    background: var(--brand-500) !important;
    color: white;
}

.sp-btn-add:hover {
    background: var(--brand-600) !important;
}

.sp-btn-remove {
    background: var(--bs-danger);
    color: white;
    width: 36px;
    height: 36px;
    padding: 0;
    font-size: 1.5em;
    line-height: 1;
}

.sp-btn-remove:hover {
    background: var(--color-ae-light);
}

/* Location rows */
.sp-location-row {
    display: grid;
    grid-template-columns: 1fr 120px 40px;
    gap: 8px;
    align-items: center;
    animation: slideIn 0.3s ease;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Pricing display */
.sp-pricing {
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.sp-price-box {
    background: white;
    border: 2px solid var(--brand-500) !important;
    border-radius: 8px;
    padding: 25px;
    text-align: center;
    box-shadow: 0 4px 12px rgb(0 0 0 / 10%);
}

.sp-price-main {
    display: flex;
    align-items: baseline;
    justify-content: center;
    gap: 2px;
    margin-bottom: 5px;
}

.sp-currency {
    font-size: 28px;
    font-weight: 600;
    color: var(--brand-500) !important;
}

.sp-price-value {
    font-size: 42px;
    font-weight: bold;
    color: var(--brand-500) !important;
    line-height: 1;
}

.sp-price-label {
    font-size: 18px;
    font-weight: 500;
    color: var(--screen-print-pricing-gray-dark);
    margin-left: 5px;
}

.sp-price-subtitle {
    font-size: 14px;
    color: var(--screen-print-pricing-gray);
    font-style: italic;
    margin-bottom: 15px;
}

.sp-divider {
    height: 1px;
    background: var(--gray-200);
    margin: 15px 0;
}

.sp-breakdown {
    text-align: left;
    margin-bottom: 15px;
}

.sp-breakdown-row {
    display: flex;
    justify-content: space-between;
    padding: 5px 0;
    font-size: 0.95em;
}

.sp-breakdown-row span:first-child {
    color: var(--screen-print-pricing-gray);
}

.sp-breakdown-row span:last-child {
    font-weight: 600;
    color: var(--screen-print-pricing-gray-dark);
}

.sp-total {
    border-top: 1px solid var(--gray-200);
    padding-top: 10px;
    margin-top: 5px;
    font-size: 1.1em;
}

.sp-total span:last-child {
    color: var(--brand-500) !important;
}

.sp-order-total {
    display: flex;
    justify-content: space-between;
    font-size: 0.9em;
    color: var(--screen-print-pricing-gray);
    padding-top: 10px;
    border-top: 1px solid var(--gray-100);
}

.sp-order-total span:last-child {
    font-weight: 600;
    color: var(--screen-print-pricing-gray-dark);
}

/* Setup details */
.sp-setup-details {
    background: var(--gray-50);
    border-radius: 4px;
    padding: 15px;
    font-size: 0.9em;
}

.sp-setup-header {
    display: flex;
    justify-content: space-between;
    font-weight: 600;
    margin-bottom: 8px;
}

.sp-setup-breakdown {
    font-size: 0.85em;
    color: var(--screen-print-pricing-gray);
    line-height: 1.6;
    padding-left: 10px;
}

/* LTM warning */
.sp-ltm-warning {
    background: var(--amber-100);
    border: 1px solid var(--amber-100);
    color: var(--bs-warning-ink);
    padding: 12px;
    border-radius: 4px;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 0.9em;
}

/* Order summary */
.sp-order-summary {
    background: white;
    border: 1px solid var(--store-line);
    border-radius: 8px;
    padding: 20px;
    margin: 20px 0;
}

.sp-order-summary h4 {
    color: var(--brand-500) !important;
    margin: 0 0 15px;
    font-size: 1.2em;
}

.sp-summary-table {
    width: 100%;
    font-size: 0.95em;
}

.sp-summary-table td {
    padding: 5px 0;
}

.sp-summary-total {
    text-align: right;
    font-weight: 600;
}

.sp-summary-divider {
    border-top: 1px solid var(--brand-100);
    padding: 5px 0;
}

.sp-summary-section {
    font-weight: 600;
    color: var(--print-ink-soft);
    padding-top: 10px;
}

.sp-summary-indent {
    padding-left: 20px;
}

.sp-summary-subtotal td {
    padding-top: 10px;
    border-top: 1px solid var(--brand-100);
}

.sp-summary-grand-total td {
    padding-top: 10px;
    border-top: 2px solid var(--brand-500) !important;
    font-size: 1.1em;
    font-weight: 600;
}

.sp-summary-grand-total .sp-summary-total {
    color: var(--brand-500) !important;
}

.sp-summary-per-item {
    background: var(--gray-50);
    font-size: 0.9em;
}

.sp-summary-per-item td {
    padding: 10px 5px;
}

/* Accordions */
.sp-accordions {
    margin-top: 30px;
}

.sp-accordion-trigger {
    width: 100%;
    background: var(--gray-50);
    border: 1px solid var(--store-line);
    border-radius: 4px;
    padding: 12px 16px;
    margin-bottom: 10px;
    cursor: pointer;
    font-size: 1em;
    font-weight: 600;
    color: var(--brand-500) !important;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: background-color 0.3s;
    text-align: left;
}

.sp-accordion-trigger:hover {
    background: var(--gray-200);
}

.sp-accordion-icon {
    transition: transform 0.3s;
    display: inline-block;
}

.sp-accordion-content {
    background: white;
    border: 1px solid var(--store-line);
    border-top: none;
    border-radius: 0 0 4px 4px;
    padding: 20px;
    margin-top: -10px;
    margin-bottom: 10px;
}

/* Pricing tiers table */
.sp-tiers-table {
    width: 100%;
    border-collapse: collapse;
}

.sp-tiers-table th,
.sp-tiers-table td {
    padding: 10px;
    text-align: center;
    border: 1px solid var(--store-line);
}

.sp-tiers-table th {
    background: var(--gray-50);
    font-weight: 600;
}

.sp-current-tier {
    background: var(--brand-100);
    font-weight: 600;
}

.sp-tier-range {
    text-align: left !important;
    font-weight: 600;
}

.sp-savings {
    color: var(--brand-500) !important;
    font-weight: 600;
}

.sp-tiers-note {
    font-size: 0.85em;
    color: var(--screen-print-pricing-gray);
    text-align: center;
    margin-top: 10px;
    font-style: italic;
}

/* Color row with safety checkbox */
.sp-color-row {
    display: flex;
    align-items: center;
    gap: 15px;
}

.sp-safety-checkbox {
    display: flex;
    align-items: center;
    gap: 8px;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    position: relative;
}

.sp-safety-checkbox input[type="checkbox"] {
    width: 16px;
    height: 16px;
    cursor: pointer;
    accent-color: var(--screen-print-pricing-orange);
}

.sp-safety-price {
    color: var(--brand-500);
    font-weight: normal;
}

/* Tooltip for safety stripes pricing */
.sp-safety-tooltip {
    position: absolute;
    bottom: 100%;
    left: 50%;
    transform: translateX(-50%) translateY(-5px);
    background: var(--screen-print-pricing-gray-dark);
    color: white;
    padding: 5px 10px;
    border-radius: 4px;
    font-size: 12px;
    white-space: nowrap;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.2s, visibility 0.2s;
    z-index: 1000;
    font-weight: normal;
}

.sp-safety-tooltip::after {
    content: '';
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    border: 5px solid transparent;
    border-top-color: var(--screen-print-pricing-gray-dark);
}

.sp-safety-checkbox:hover .sp-safety-tooltip {
    opacity: 1;
    visibility: visible;
}

/* Safety label styling */
.sp-safety-label {
    color: var(--screen-print-pricing-orange);
    font-size: 0.9em;
}

/* Compact safety checkbox for additional locations */
.sp-location-row .sp-safety-checkbox {
    margin-left: 10px;
}

/* Keep full text for front safety checkbox */
.sp-front-safety .sp-safety-label {
    color: inherit;
    font-size: inherit;
}

/* Safety row in order summary */
.sp-safety-row {
    background-color: var(--red-50);
}

.sp-safety-row td {
    color: var(--screen-print-pricing-red-2);
    font-weight: 500;
}

/* Location row styling */
.sp-location-row {
    display: grid;
    grid-template-columns: 180px minmax(250px, 1fr) 50px;
    gap: 15px;
    align-items: center;
    margin-bottom: 10px;
    animation: slideIn 0.3s ease;
}

/* Size Upcharge Info Box */
.sp-size-upcharge-info {
    background: linear-gradient(135deg, var(--store-green-50) 0%, var(--brand-100) 100%);
    border: 1px solid var(--store-line);
    border-radius: 8px;
    padding: 15px;
    margin-top: 30px;
    margin-bottom: 20px;
    box-shadow: 0 2px 4px rgb(0 0 0 / 5%);
}

.sp-size-upcharge-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--store-line);
}

.sp-size-icon {
    font-size: 24px;
}

.sp-size-title {
    font-size: 1.1em;
    font-weight: 600;
    color: var(--brand-500) !important;
}

.sp-size-upcharge-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px;
}

.sp-size-item {
    background: white;
    border: 1px solid var(--gray-200);
    border-radius: 6px;
    padding: 10px;
    text-align: center;
    transition: all 0.2s ease;
}

.sp-size-item:hover {
    border-color: var(--brand-500) !important;
    box-shadow: 0 2px 6px rgb(46 88 39 / 10%);
    transform: translateY(-1px);
}

.sp-size-label {
    display: block;
    font-weight: 600;
    color: var(--screen-print-pricing-gray-dark);
    margin-bottom: 5px;
    font-size: 0.95em;
}

.sp-size-price {
    display: block;
    color: var(--brand-500) !important;
    font-weight: 500;
    font-size: 1.05em;
}

.sp-size-item:first-child .sp-size-price {
    color: var(--screen-print-pricing-gray);
    font-style: italic;
}

/* Responsive */

/* DTG-Style Layout Responsiveness */
@media (width <= 1024px) {
    .pricing-calculator-section {
        padding: 20px;
    }
}

@media (width <= 768px) {
    /* Stack two-column grid on mobile */
    .product-content {
        grid-template-columns: 1fr;
    }

    .product-image-section,
    .product-info-section {
        padding: 30px 20px;
    }

    .main-image-container {
        height: 350px;
    }

    .product-hero-section {
        margin-bottom: 30px;
    }

    .pricing-calculator-section {
        padding: 15px;
    }

    .container {
        padding: 0 15px;
    }

    .sp-layout {
        grid-template-columns: 1fr;
        gap: 20px;
    }

    .sp-price-value {
        font-size: 36px;
    }

    .sp-currency {
        font-size: 24px;
    }

    .sp-location-row {
        grid-template-columns: 1fr;
        gap: 8px;
    }

    .sp-location-row select {
        width: 100%;
    }

    .sp-btn-remove {
        width: 100%;
        margin-top: 5px;
    }

    .sp-color-row {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .sp-safety-checkbox {
        width: 100%;
    }

    .sp-size-upcharge-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (width <= 480px) {
    .product-hero-section,
    .pricing-calculator-section {
        border-radius: 12px;
    }

    .product-image-section,
    .product-info-section {
        padding: 20px 15px;
    }

    .main-image-container {
        height: 300px;
    }

    .product-title {
        font-size: 24px;
    }

    .pricing-calculator-section {
        padding: 0;
    }

    .sp-size-upcharge-grid {
        grid-template-columns: 1fr;
    }
}

